const resp = $json;
let parsed = null;
try {
  const text = (((resp.candidates || [])[0] || {}).content || {}).parts?.map(p => p.text).join('') || '';
  parsed = JSON.parse(text.replace(/^```json\s*|\s*```$/g, '').trim());
} catch (e) { parsed = null; }
const usage = resp.usageMetadata || null;
if (!parsed) {
  return [{ json: { qc_ran: true, qc_parse_failed: true, would_pass_qc: true, model_would_pass_qc: null, issues: [], gemini_usage: usage } }];
}
const issues = Array.isArray(parsed.issues) ? parsed.issues : [];
const sevRank = { low: 1, medium: 2, high: 3 };
// Categories that must fail QC on a SINGLE medium+ occurrence (2026-09-09 stricter QC
// requirement) rather than only via the old 3-medium-issues-of-any-kind aggregate floor,
// which was too lenient for these specific, well-understood problem types.
const MEDIUM_PLUS_FAIL = new Set(['exact_repeated_moment', 'developer_publisher_logo_filler', 'title_card_filler']);
// Categories that must fail QC at ANY severity: by definition (see prompt) the model only
// reports these when genuinely non-contextual/gratuitous, so there is no acceptable low-severity
// case once one has been reported. Includes sub_1s_cut, which also covers tiny tail fragments.
const ANY_SEVERITY_FAIL = new Set(['esrb_rating_card_filler', 'platform_storefront_card_filler', 'sub_1s_cut', 'narration_visual_mismatch', 'accessibility_narration_over_unrelated_footage', 'rapid_cut_cluster', 'excessive_trailer_pacing']);
let computedFail = false, otherMediumPlusCount = 0;
for (const issue of issues) {
  const cat = String(issue.category || '');
  const rank = sevRank[String(issue.severity || '').toLowerCase()] || 0;
  if (rank >= 3) { computedFail = true; continue; }
  if (ANY_SEVERITY_FAIL.has(cat) && rank >= 1) { computedFail = true; continue; }
  if (MEDIUM_PLUS_FAIL.has(cat) && rank >= 2) { computedFail = true; continue; }
  if (rank >= 2) otherMediumPlusCount += 1;
}
// Catch-all floor for categories not explicitly named above (e.g. near_duplicate_moment,
// irrelevant_footage, jarring_internal_cut, excessive_environment_reuse, other): kept
// deliberately looser since near-duplicate perceptual matching has known false positives
// (see Phase 1 flag-only decision) -- 3+ medium issues of these kinds, or any single high.
if (otherMediumPlusCount >= 3) computedFail = true;
return [{ json: {
  qc_ran: true,
  qc_parse_failed: false,
  issues,
  overall_pacing_assessment: String(parsed.overall_pacing_assessment || ''),
  real_footage_confidence: String(parsed.real_footage_confidence || 'unknown'),
  would_pass_qc: !computedFail,
  model_would_pass_qc: parsed.would_pass_qc !== false,
  gemini_usage: usage,
} }];
